package io.github.ningpp.compat;

/** Replacement for System.Data.DeletedRowInaccessibleException (generated by CSharpToJava converter). */
public class DeletedRowInaccessibleException extends DataException {
    public DeletedRowInaccessibleException() { super(); }
    public DeletedRowInaccessibleException(String message) { super(message); }
    public DeletedRowInaccessibleException(String message, Throwable cause) { super(message, cause); }
}
